function createWordingSimulationUI(box,stage){
 const controls=elem('div','wording-only');controls.id='wordingControls';
 controls.innerHTML='<p id="wordingComputing" role="status" class="sim-hint"></p><div class="wording-view-controls"><label class="check"><input id="wordingPullApart" type="checkbox" checked>Pull pieces apart</label></div><button class="btn" id="wordingRandomDraw" type="button">New random draw</button>';
 $('removalStats').after(controls);
 const lower=elem('section','color-description wording-comparison');lower.id='wordingComparison';lower.hidden=true;
 stage.after(lower);lower.append($('simulationMethods'),$('wordingSimulationMethods'));
 const curves=elem('div','wording-curves');curves.innerHTML='<div><h3>Largest piece · share of starting phrases</h3><div id="wordingCurveL"></div></div><div><h3>Fragmentation</h3><div id="wordingCurveF"></div></div>';lower.append(curves);
 const legend=elem('div','wording-curve-legend'),note=elem('p','sim-hint');lower.append(legend,note);
 function pending(message){$('wordingComputing').textContent=message;curves.hidden=legend.hidden=note.hidden=!!message;}
 function chart(d,field,k,selected,series){
  const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 480 225');svg.setAttribute('role','img');svg.setAttribute('aria-label',field==='F'?'Fragmentation by number of removed phrases':d.severity?'Largest-piece share of starting nodes by removals':'Largest-piece share of starting phrases by removals');
  const add=(tag,attrs,text,parent=svg)=>{const n=document.createElementNS(ns,tag);for(const[a,v]of Object.entries(attrs))n.setAttribute(a,v);if(text!==undefined)n.textContent=text;parent.append(n);return n;};
  const x=i=>40+420*i/Math.max(1,d.kmax),y=v=>183-155*v;
  for(const value of [0,.25,.5,.75,1]){add('line',{x1:40,x2:460,y1:y(value),y2:y(value),stroke:'#e0e8eb'});add('text',{x:34,y:y(value)+4,'text-anchor':'end'},`${Math.round(value*100)}%`);}
  for(let i=0;i<=d.kmax;i+=d.kmax>10?5:1)add('text',{x:x(i),y:201,'text-anchor':'middle'},String(i));
  add('text',{x:250,y:220,'text-anchor':'middle'},'Phrases removed');
  for(const[key,label,color]of series){const values=d.curves[key],path=add('path',{d:values.map((r,i)=>`${i?'L':'M'}${x(i)},${y(r[field])}`).join(''),fill:'none',stroke:color,'stroke-width':selected===key?3:1.6,'stroke-dasharray':key==='random'?'5 3':'none','data-strategy':key});add('title',{},label,path);}
  add('line',{x1:x(k),x2:x(k),y1:25,y2:185,stroke:'#234758','stroke-dasharray':'3 4','data-current-removals':k});return svg;
 }
 function renderCharts(d,k,strategy,series){
  curves.hidden=legend.hidden=note.hidden=false;
  curves.querySelector('h3').textContent=d.severity?'Largest piece · share of starting nodes':'Largest piece · share of starting phrases';
  legend.replaceChildren();for(const[key,label,color]of series){const item=elem('span'),dot=elem('span','dot');dot.style.background=color;item.append(dot,document.createTextNode(label));legend.append(item);}
  $('wordingCurveL').replaceChildren(chart(d,'lccShare',k,strategy,series));$('wordingCurveF').replaceChildren(chart(d,'F',k,strategy,series));
 }
 function renderSeverity(d,k,strategy){
  renderCharts(d,k,strategy,d.series);
  note.textContent='Only care phrases are removed; severity diamonds remain. Largest piece divides by all starting nodes (phrases + diamonds). Fragmentation = 1 − Σ sᵢ(sᵢ − 1) / [n(n − 1)], using surviving component sizes sᵢ and surviving nodes n (0 when n < 2). The target line ends when its separation goal is met; comparison lines continue to the removal limit. Random is one fixed draw.';
 }
 function render(d,k,strategy,removed,seed){
  pending('');const ids=d.nodes.map(n=>n.id),adj=Breakup.adjacency(ids,d.edges),stats=Breakup.stats(adj,ids,new Set(removed));
  $('wordingRandomDraw').hidden=strategy!=='random';renderCharts(d,k,strategy,WORDING_CHART_STRATEGIES);
  note.textContent='Best sets are exact through 3 removals and best found above 3. Each removal count is optimized separately, so phrases can return between snapshots.';
  return stats;
 }
 return{controls,lower,pending,render,renderSeverity};
}

/* Research context for the home-health-specific, protected-diamond vertex cut. */
function simulationMethodCard(){
 const section=elem('section','simulation-methods');section.id='simulationMethods';section.setAttribute('aria-label','Shortest removal route math and research');
 section.innerHTML=`<h3>Protected-node vertex cuts</h3>
 <div class="reading-row"><p><b>Aim.</b> Remove care issues to break the wording network apart, separating every screening diamond from the main network with as few removals as possible.</p><div class="simulation-equation"><math xmlns="http://www.w3.org/1998/Math/MathML" aria-label="Minimize the number of removed phrases R"><mrow><munder><mo>min</mo><mi>R</mi></munder><mo>|</mo><mi>R</mi><mo>|</mo></mrow></math></div></div>
 <div class="reading-row"><p><b>Targeted fragmentation.</b> Removing selected care-issue nodes breaks connecting paths, separating screened care issues (diamonds) from the main network. For this simulation, separation succeeds when all screening diamonds sit outside a main component containing more than half of the remaining nodes. Diamonds stay visible.</p><div class="simulation-equation"><math xmlns="http://www.w3.org/1998/Math/MathML" aria-label="The main component C contains no diamond from D, and twice its size exceeds the number of surviving nodes"><mrow><mi>C</mi><mo>∩</mo><mi>D</mi><mo>=</mo><mo>∅</mo><mo>,</mo><mspace width=".5em"/><mn>2</mn><mo>|</mo><mi>C</mi><mo>|</mo><mo>&gt;</mo><mo>|</mo><mi>V</mi><mo>|</mo><mo>−</mo><mo>|</mo><mi>R</mi><mo>|</mo></mrow></math></div></div>
 <p id="simulationMethodStatus"></p>
 <details><summary>Optimization technique</summary>
 <p>The reference calculation uses mixed-integer linear programming (SciPy / HiGHS). Binary xᵥ marks a removed node and yᵥ marks membership in C. Diamond removal is forbidden. The objective prioritizes fewer removals, then the largest qualifying C:</p>
 <div class="simulation-equation"><math xmlns="http://www.w3.org/1998/Math/MathML" aria-label="Minimize N plus one times the sum of removal indicators x, minus the sum of main component indicators y"><mrow><mo>min</mo><mspace width=".4em"/><mo>(</mo><mi>N</mi><mo>+</mo><mn>1</mn><mo>)</mo><mo>∑</mo><msub><mi>x</mi><mi>v</mi></msub><mo>−</mo><mo>∑</mo><msub><mi>y</mi><mi>v</mi></msub></mrow></math></div>
 <p>N = |V|. A node cannot be removed and kept in C. For each directed version of an edge u–v, yᵤ ≤ yᵥ + xᵥ forces any surviving neighbor of C to belong to C. A single-root flow constraint makes C connected. The majority constraint is 2∑y ≥ N − ∑x + 1; diamond indicators satisfy x = y = 0.</p>
 <p>The saved solver result reports an optimal solution at zero relative MIP gap. The browser replays a sequential ordering of that set; it does not run the integer solver. The minimum applies to the complete removal set, not a unique ordering or a shortest walk between two nodes. Filtered graphs use the labeled greedy strategy; manual choices and other removal orders do not carry an optimality claim.</p>
 <p><a href="https://docs.scipy.org/doc/scipy/reference/generated/scipy.optimize.milp.html" target="_blank" rel="noopener noreferrer">SciPy mixed-integer optimization documentation</a></p></details>
 <details><summary>Research behind node-removal methods</summary>
 <p><a href="https://doi.org/10.1007/s10588-006-7084-x" target="_blank" rel="noopener noreferrer">Borgatti (2006), Identifying sets of key players in a social network</a>, Computational &amp; Mathematical Organization Theory, 12, 21–34. Studies selecting sets of nodes for network disruption; centrality rankings alone need not yield an optimal set.</p>
 <p><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC5098660/" target="_blank" rel="noopener noreferrer">Braunstein, Dall’Asta, Semerjian &amp; Zdeborová (2016), Network dismantling</a>, PNAS, 113, 12368–12373. Studies minimizing removals to break networks into small components.</p>
 <p>These studies provide methodological context. Our protected diamonds and majority-main-piece requirement are specific to this simulation; the studies do not establish a home-health result or its clinical meaning. Component colors show reachability after removal.</p></details>`;
 return section;
}

function wordingSimulationMethodCard(){
 const section=elem('section','simulation-methods');section.id='wordingSimulationMethods';section.setAttribute('aria-label','Network dismantling and fragmentation');
 section.innerHTML=`<h3>Network dismantling and fragmentation</h3><div class="reading-row"><p><b>Fragmentation.</b> How often two surviving phrases cannot reach each other through the remaining links. Zero means connected; one means fully isolated.</p><div id="wordingFragmentationFormula" class="reading-formula"><math xmlns="http://www.w3.org/1998/Math/MathML"><mrow><mi>F</mi><mo>=</mo><mn>1</mn><mo>−</mo><mfrac><mrow><mo>∑</mo><msub><mi>s</mi><mi>i</mi></msub><mo>(</mo><msub><mi>s</mi><mi>i</mi></msub><mo>−</mo><mn>1</mn><mo>)</mo></mrow><mrow><mi>n</mi><mo>(</mo><mi>n</mi><mo>−</mo><mn>1</mn><mo>)</mo></mrow></mfrac></mrow></math></div></div>
 <details><summary>Technique, theory and references</summary><p>Best set to shatter maximizes F, breaking ties by a smaller largest piece. Best set to shrink minimizes the largest piece, breaking ties by higher F. Final ties use the reference’s comma-joined sorted node-ID text rule. Bridge attacks recompute unweighted Brandes betweenness; adaptive hubs recompute degree. Most common phrases uses record frequency, independently of agency-based node size. The Random strategy uses seeded draws; the charts show only the two best-set methods and most common phrases.</p><p>Link weights select the displayed graph; the breakup calculations treat surviving links as unweighted. All phrases are removable. There are no protected targets, majority-main-network condition or goal-based playback stops in this wording view. Play runs to 20 removals. Removed phrases disappear. Their deleted links remain as faint background lines only and never count in connectivity. Pull-apart positions are illustrative.</p><p><a href="https://doi.org/10.1007/s10588-006-7084-x" target="_blank" rel="noopener noreferrer">Borgatti (2006), Identifying sets of key players in a social network</a> supplies the node-set disruption and fragmentation context. <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC5098660/" target="_blank" rel="noopener noreferrer">Braunstein et al. (2016), Network dismantling</a> studies removal sets that break networks apart. These are wording relationships, not provider ties, clinical effects or patient-harm measures.</p></details>`;
 return section;
}
function installSimulationMathGuides(){
 const defs=[['wordingFragmentationFormula','Fragmentation','One minus the share of surviving ordered node pairs that are in the same connected piece.',[['F','Fragmentation, from 0 to 1.'],['sᵢ','Number of surviving phrases in connected piece i.'],['Σ','Sum across every surviving piece, including singletons.'],['sᵢ(sᵢ−1)','Ordered pairs of different phrases that can still reach each other in that piece.'],['n','Number of phrases remaining, after removals.'],['n(n−1)','All ordered pairs of different surviving phrases.'],['Edge cases','The reference uses F = 1 when fewer than two phrases remain.']]],
 ['wordingLargestFormula','Largest-piece share','The size of the largest surviving component divided by the number of starting phrases.',[['L','Share of the original graph retained in its largest surviving piece.'],['maxᵢ sᵢ','Number of phrases in the largest surviving component.'],['N₀','All phrases in the starting filtered graph. This denominator does not shrink as phrases are removed.'],['Percentage','Multiply L by 100. A value below 50% marks the requested breaking point.']]],
 ['wordingCutFormula','Minimum vertex cut','The smallest removal set that disconnects the starting graph.',[['κ (kappa)','Node connectivity: the size of a minimum vertex cut.'],['R','A set of phrases removed along with their incident links.'],['|R|','The number of removed phrases.'],['Condition','G minus R must be disconnected. For an already disconnected graph the cut is empty; complete graphs use the standard connectivity convention.'],['Meaning','Any split qualifies, including isolating one phrase. This differs from maximizing fragmentation at a chosen removal count.']]]];
 for(const[id,title,note,symbols]of defs){if(!$(id))continue;const expression=$(id).querySelector('math').innerHTML;readingFormula(id,expression,note,symbols,title);}
 const severity=[...$('simulationMethods').querySelectorAll('.simulation-equation')];severity.forEach((box,i)=>{const expression=box.querySelector('math').innerHTML;box.id='severityCutFormula'+i;box.classList.add('reading-formula');readingFormula(box.id,expression,i===0?'Minimize the number of phrases removed while disconnecting all diamonds from a majority main component.':i===1?'The main connected component contains no protected diamond and has more than half of the surviving nodes.':'The integer-program objective minimizes removals first, then favors the largest qualifying main component.',[['R','Removed care phrases; diamonds cannot be removed.'],['C','A complete connected main component after removal.'],['D','Protected severity-family diamonds.'],['V or N','All starting nodes, including diamonds.'],['xᵥ','Binary indicator that a phrase is removed.'],['yᵥ','Binary indicator that a node belongs to C.'],['Scope','The exact 33-phrase result applies only when the graph matches the saved severity reference.']], 'Protected-node vertex cut');});
}

