  const camera=network.getViewPosition(),scale=network.getScale();setSimulationData({nodes:nodes.map(n=>({...n,...positions.get(n.id),fixed:{x:true,y:true},color:nodeColor(n)})),edges:edges.map(e=>({...e,...(grouped?{color:{...e.color,color:colors.get(e.from),highlight:colors.get(e.from),hover:colors.get(e.from)}}:{})}))});
